// Search client, driving the Pagefind JS API.
//
// WHY THIS LIVES IN public/ AND NOT IN THE COMPONENT
//
// Pagefind's index is generated by a step that runs *after* `astro build`, so
// `/pagefind/pagefind.js` does not exist while Vite is bundling. Every way of
// asking Vite to leave that import alone failed differently:
//
//   - a plain string literal fails `astro dev` outright (import-analysis
//     cannot resolve it);
//   - `/* @vite-ignore */` does not suppress import-analysis inside an Astro
//     <script>;
//   - building the path at runtime got past both, but Vite still wrapped the
//     call in its preload helper and emitted a literal `__VITE_PRELOAD__` into
//     the inlined module, which throws a ReferenceError on first search.
//
// Files in public/ are copied verbatim and never parsed, so the import here is
// exactly what reaches the browser. This is the same arrangement analytics.js,
// external-links.js and tablesort.js already use, rather than a new exception.
//
// Markup and styling stay in src/components/site/Search.astro.

const dialog = document.querySelector('[data-search-dialog]');
const input = document.querySelector('[data-search-input]');
const panel = document.querySelector('[data-search-results]');

if (dialog && input && panel) {
  let pagefind = null;
  let loadFailed = false;
  // Guards against an older, slower query overwriting a newer one's results.
  let seq = 0;

  const say = (message) => {
    panel.innerHTML = '<p class="search-msg"></p>';
    panel.firstElementChild.textContent = message;
  };

  // Loaded on first open rather than on page load: the index is 75 pages of
  // data and most visits never search.
  async function load() {
    if (pagefind || loadFailed) return;

    let module;
    try {
      module = await import('/pagefind/pagefind.js');
    } catch {
      // The expected reason to land here is `astro dev`, where the index has
      // never been generated. Kept narrow on purpose — wrapping the setup calls
      // below in the same try is what made an API mismatch report itself as
      // "no index" and fail silently on the built site.
      loadFailed = true;
      say('Search runs on the built site. Run `npm run build && npm run preview` to try it locally.');
      return;
    }

    // `options()` is not among Pagefind 1.5's module exports; `init()` is. Both
    // are optional here so a version that restores or drops either degrades to
    // working search rather than none.
    await module.options?.({ excerptLength: 24 });
    await module.init?.();
    pagefind = module;
  }

  async function run(query) {
    const mine = ++seq;

    if (!query.trim()) {
      panel.innerHTML = '';
      return;
    }

    await load();
    if (!pagefind || mine !== seq) return;

    const search = await pagefind.debouncedSearch(query, {}, 180);
    // Null means debounce cancelled this call; a bumped seq means a later
    // keystroke already superseded it.
    if (!search || mine !== seq) return;

    const hits = await Promise.all(search.results.slice(0, 8).map((r) => r.data()));
    if (mine !== seq) return;

    if (hits.length === 0) {
      say(`No results for "${query}".`);
      // analytics.js listens for this to record search_no_results.
      document.dispatchEvent(new CustomEvent('wiki:search-empty', { detail: { query } }));
      return;
    }

    panel.innerHTML = '';
    for (const hit of hits) {
      const a = document.createElement('a');
      a.className = 'search-hit';
      a.href = hit.url;

      const title = document.createElement('span');
      title.className = 'search-hit__title';
      title.textContent = hit.meta?.title ?? hit.url;
      a.append(title);

      const crumb = document.createElement('span');
      crumb.className = 'search-hit__crumb';
      crumb.textContent = decodeURI(hit.url).replace(/\/$/, '') || '/';
      a.append(crumb);

      // Pagefind wraps matches in <mark>. The excerpt is built from indexed
      // page text, not from the query, so it is our own content either way.
      const excerpt = document.createElement('p');
      excerpt.className = 'search-hit__excerpt';
      excerpt.innerHTML = hit.excerpt;
      a.append(excerpt);

      panel.append(a);
    }
  }

  const open = () => {
    if (!dialog.open) dialog.showModal();
    input.focus();
    input.select();
  };

  for (const button of document.querySelectorAll('[data-search-open]')) {
    button.addEventListener('click', open);
  }
  for (const button of document.querySelectorAll('[data-search-close]')) {
    button.addEventListener('click', () => dialog.close());
  }

  input.addEventListener('input', () => run(input.value));
  document.querySelector('[data-search-form]')?.addEventListener('submit', (e) => e.preventDefault());

  // Clicking outside the panel closes it. A <dialog>'s backdrop counts as the
  // dialog itself as an event target, so compare against its box instead.
  dialog.addEventListener('click', (event) => {
    const box = dialog.getBoundingClientRect();
    const outside =
      event.clientY < box.top ||
      event.clientY > box.bottom ||
      event.clientX < box.left ||
      event.clientX > box.right;
    if (outside) dialog.close();
  });

  document.addEventListener('keydown', (event) => {
    const target = event.target;
    const typing =
      target?.tagName === 'INPUT' ||
      target?.tagName === 'TEXTAREA' ||
      target?.isContentEditable;

    if (!typing && event.key === '/') {
      event.preventDefault();
      open();
    }
    if ((event.ctrlKey || event.metaKey) && event.key === 'k') {
      event.preventDefault();
      open();
    }
  });
}
